// 3D model of the right temporal bone and ear from Z-Anatomy meshes (CC BY-SA
// 4.0, based on BodyParts3D): the temporal bone (translucent), auricle,
// eardrum, ossicles, cochlea and labyrinth, the facial nerve through the bone,
// chorda tympani, VIII, the petrous carotid and the sigmoid sinus. The auricle
// is Z-Anatomy's skin patches joined into one surface; the ear canal, the
// honeycomb of mastoid air cells and the antrum, tensor tympani and stapedius
// are sculpted for this app. Geometry and the traced courses live in
// data/temporal-bone-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres centred on the middle ear: +y = superior,
// +z = anterior, and lateral (the patient's right) is -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.temporal_bone = {
  // Default view: from above and in front of the right ear, looking down
  // through the translucent bone at the ossicles, labyrinth and the honeycomb
  // of mastoid air cells, with the auricle to the side.
  camera: { target: [0.2, 0.1, -0.2], radius: 11.5, theta: -0.65, phi: 1.0 },

  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [-1.2, 0.25],
    // Down the ear canal at the eardrum, as through an otoscope: only the
    // canal, eardrum and ossicles stay ("Show hidden" brings the rest back).
    anterior: [-1.559, 1.784, 1.5, [0.186, -0.024, 0.357], ["temporal", "auricle", "cochlea", "labyrinth", "facial_nerve", "cn8",
      "antrum", "air_cells", "sigmoid", "ijv", "ica", "tensor_tympani", "stapedius", "auditory_tube", "digastric_post", "scm"]]
  },
  viewLabels: { inferior: "From above", anterior: "Otoscope" },

  // Starting axial level (0 = bottom, 1 = top): through the middle ear.
  sectionLevel: 0.5,

  look: {
    temporal: { kind: "bone", opacity: 0.28 },
    auricle: { kind: "skin" },
    eac: { kind: "skin", color: 0xd9a089, ao: 0.45 },
    tympanic_membrane: { kind: "membrane", opacity: 0.82, ao: 0 },
    malleus: { kind: "bone", color: 0xf1e3c2 },
    incus: { kind: "bone", color: 0xead8b0 },
    stapes: { kind: "bone", color: 0xe3cc98 },
    tensor_tympani: { kind: "muscle", color: 0xb5524a },
    stapedius: { kind: "muscle", color: 0xa94b45 },
    // Antrum and air cells as a cast of the air spaces: pale, mucosa-lined cells.
    antrum: { kind: "mucosa", color: 0xd9c4bb, ao: 0.4 },
    air_cells: { kind: "mucosa", color: 0xe6d8d0, ao: 0.45 },
    auditory_tube: { kind: "cartilage", color: 0xd9c2b8 },
    cochlea: { kind: "gland", color: 0xe0b98c },
    labyrinth: { kind: "gland", color: 0xd7a971 },
    facial_nerve: { kind: "nerve" },
    chorda: { kind: "nerve", color: 0xf3d97a },
    cn8: { kind: "nerve", color: 0xe8c45a },
    ica: { kind: "artery" },
    sigmoid: { kind: "vein" },
    ijv: { kind: "vein" },
    digastric_post: { kind: "muscle", color: 0xa4423f, opacity: 0.8 },
    scm: { kind: "muscle", color: 0x9c3a3c, opacity: 0.6 }
  },

  build(THREE, h) {
    return h.fromMeshes("temporal_bone", this.look);
  }
};
